export interface IconDefinition {
  /** Symbol id of the outlined icon in `pix-sprite.svg` (the icon name). */
  default: string;
  /** Symbol id of the filled variant (`<icon name>_plain`), when the icon has one. */
  plainIcon?: string;
}

/**
 * Icon names accepted by the PixIcon components, mapped to sprite symbol ids.
 * Generated by `pnpm build` from the folders of `tooling/generate-svg-sprite/icons`.
 */
export declare const ICONS: Record<string, IconDefinition>;
